import { isCi } from "../env.js";
import chalk from "chalk";
//#region src/init/chrome.ts
const NEON_GREEN = "#4BB578";
const INIT_BANNER_LINES = [
	" ██╗  ██╗██████╗  ██████╗ ██╗  ██╗",
	" ███╗ ██║██╔═══╝ ██╔═══██╗███╗ ██║",
	" ████╗██║██████╗ ██║   ██║████╗██║",
	" ██╔████║██╔═══╝ ██║   ██║██╔████║",
	" ██║╚███║██████╗ ╚██████╔╝██║╚███║",
	" ╚═╝ ╚══╝╚═════╝  ╚═════╝ ╚═╝ ╚══╝"
];
const formatInitBanner = () => INIT_BANNER_LINES.join("\n");
const shouldPrintInitBanner = (yes) => !yes && !isCi() && Boolean(process.stdout.isTTY);
const printInitBanner = () => {
	process.stdout.write(`\n${chalk.hex(NEON_GREEN)(formatInitBanner())}\n\n${chalk.dim("Let's get this directory set up with Neon.")}\n\n`);
};
const formatInitDone = (input) => {
	const labelWidth = Math.max(0, ...input.rows.map((row) => row.label.length));
	const body = input.rows.length === 0 ? "" : `\n\n${input.rows.map((row) => `  ${row.label.padEnd(labelWidth)}  ${row.value}`).join("\n")}`;
	const next = input.next.length === 0 ? "" : `\n\nNext:\n${input.next.map((line) => `  ${line}`).join("\n")}`;
	const rule = "-".repeat(input.heading.length);
	return `${input.heading}\n${rule}${body}${next}\n`;
};
const printInitDone = (text) => {
	const painted = (text.endsWith("\n") ? text.slice(0, -1) : text).split("\n").map((line, index) => {
		if (index === 0) return chalk.hex(NEON_GREEN).bold(line);
		if (/^-{3,}$/.test(line)) return chalk.hex(NEON_GREEN)(line);
		if (line === "Next:") return chalk.bold(line);
		return line;
	});
	process.stdout.write(`\n${painted.join("\n")}\n\n`);
};
const agentSetupLabel = (setup) => {
	if (setup === "plugin") return "plugin";
	if (setup === "skills-mcp") return "skills and MCP";
	return "skipped";
};
const agentSetupDoneLabel = (input) => {
	if (!input.ran && input.setup !== "skip") return "not run";
	return agentSetupLabel(input.setup);
};
//#endregion
export { INIT_BANNER_LINES, NEON_GREEN, agentSetupDoneLabel, agentSetupLabel, formatInitBanner, formatInitDone, printInitBanner, printInitDone, shouldPrintInitBanner };
